content.text:
{
  "decision": "write",
  "essentials": [
    {
      "name": "Crazy House",
      "local_name": "Biệt thự Hằng Nga",
      "kind": "other",
      "area": null,
      "why": {
        "en": "A striking, not-quite-finished Gaudi-esque fantasy house designed by the daughter of an independence war hero, well worth a visit even if you are not too interested in architecture.",
        "vi": "Một ngôi nhà kỳ ảo mang phong cách Gaudi chưa hoàn thiện do con gái một anh hùng chiến tranh thiết kế, rất đáng ghé thăm dù bạn không quá quan tâm đến kiến trúc."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A striking, not-quite-finished Gaudi-esque fantasy house designed by the daughter of an independence war hero."
    },
    {
      "name": "Xuan Huong Lake",
      "local_name": "Hồ Xuân Hương",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A public lake in the centre, about 5 km in length, where honeymooners and locals stroll its banks and boats can be rented on both sides.",
        "vi": "Hồ công cộng ngay trung tâm, dài khoảng 5 km, nơi các cặp đôi và người dân địa phương dạo bộ ven bờ và có thể thuê thuyền ở hai phía."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Now, Xuan Huong Lake is one of the main draws of Da Lat, and you can see honeymooners and locals strolling its banks."
    },
    {
      "name": "Dalat Market",
      "local_name": "Chợ Đà Lạt",
      "kind": "market",
      "area": null,
      "why": {
        "en": "Filled with local specialities like strawberry jam, fruit conserves, avocado and artichokes, and the best place in town to eat fresh fruits and vegetables.",
        "vi": "Đầy ắp đặc sản địa phương như mứt dâu, trái cây bảo quản, bơ và atisô, đồng thời là nơi tuyệt nhất trong thành phố để ăn trái cây và rau củ tươi."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Filled with local specialities: strawberry jam, fruit conserves, avocado, artichokes."
    },
    {
      "name": "Truc Lam Zen Monastery",
      "local_name": "Thiền viện Trúc Lâm",
      "kind": "temple_shrine",
      "area": null,
      "why": {
        "en": "A peaceful monastery with a magnificent view over the dams below and gardens full of landscaped shrubs in animal form, best reached by cable car over the pine forest.",
        "vi": "Một thiền viện yên bình với tầm nhìn tuyệt đẹp xuống các con đập bên dưới và những khu vườn đầy cây cảnh tạo hình thú, đến bằng cáp treo qua rừng thông là đẹp nhất."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The monastery has a magnificent view over the dams below and its gardens are full of landscaped shrubs in animal form."
    },
    {
      "name": "Linh Phuoc Pagoda",
      "local_name": "Chùa Linh Phước",
      "kind": "temple_shrine",
      "area": null,
      "why": {
        "en": "A one-of-a-kind kitschy temple in Vietnam, where broken porcelain is used to compose beautiful mosaics that adorn the whole 7-level pagoda.",
        "vi": "Một ngôi chùa độc nhất vô nhị ở Việt Nam, nơi sành vỡ được dùng để tạo nên những bức khảm tuyệt đẹp trang trí toàn bộ ngôi chùa 7 tầng."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Broken porcelain is used to compose beautiful mosaics that adorn the whole of this 7-level pagoda, and it is still expanding."
    },
    {
      "name": "Langbiang Mountain",
      "local_name": "Núi Langbiang",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "There are two peaks, 1915 m and 2167 m; the first is reachable by a steep paved path or Jeep, while the second is a great 2-3 hour hike.",
        "vi": "Có hai đỉnh cao 1915 m và 2167 m; đỉnh thứ nhất có thể lên bằng đường dốc lát đá hoặc xe Jeep, còn đỉnh thứ hai là một cung leo núi tuyệt vời kéo dài 2-3 giờ."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "There are 2 peaks: 1915 m and 2167 m."
    },
    {
      "name": "Valley of Love",
      "local_name": "Thung Lũng Tình Yêu",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A common stop on Dalat tours and very popular with honeymooners, also a great spot for canyoning.",
        "vi": "Một điểm dừng quen thuộc trong các tour Đà Lạt và rất được các cặp đôi hưởng tuần trăng mật yêu thích, cũng là nơi tuyệt vời để chơi canyoning."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The Valley of Love is common stop on Dalat tours and is very popular with honeymooners."
    },
    {
      "name": "Pongour Falls",
      "local_name": "Thác Pongour",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "One of the largest and widest waterfalls in Vietnam, a magnificent sight during the wet season.",
        "vi": "Một trong những thác nước lớn và rộng nhất Việt Nam, là cảnh tượng tráng lệ vào mùa mưa."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "It's one of the largest and widest waterfalls in Vietnam and during the wet season is a magnificent sight."
    },
    {
      "name": "Tuyen Lam Lake",
      "local_name": "Hồ Tuyền Lâm",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Its clean green waters stretch over an immense 350 ha, known as the lake where rivers, springs, and forests meet, with Voi Mountain on the other side good for hiking.",
        "vi": "Mặt nước xanh trong trải rộng trên 350 ha, được biết đến là nơi sông, suối và rừng gặp nhau, phía bên kia hồ là núi Voi thích hợp để leo núi."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Its waters stretch over an immense 350 ha and because of its various sources, Tuyen Lam is known as the lake where rivers, springs, and forests meet."
    },
    {
      "name": "Nha Tho Domaine de Marie",
      "local_name": "Nhà thờ Domaine de Marie",
      "kind": "temple_shrine",
      "area": null,
      "why": {
        "en": "A pink church on top of a hill, with a store selling various dried fruits and snacks from the local orchards run by the nuns of the monastery.",
        "vi": "Một nhà thờ màu hồng trên đỉnh đồi, có cửa hàng bán các loại trái cây sấy và đồ ăn vặt từ vườn cây địa phương do các nữ tu của tu viện điều hành."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A pink church on top of a hill, with a store selling various dried fruits and snacks from the local orchards run by the nuns of the monastery."
    },
    {
      "name": "Palace III",
      "local_name": "Dinh III",
      "kind": "museum",
      "area": null,
      "why": {
        "en": "A museum that displays the beautiful original 1930s furniture from the colonial era summer home of the last emperor of Vietnam.",
        "vi": "Một bảo tàng trưng bày những món đồ nội thất nguyên bản tuyệt đẹp từ thập niên 1930 của dinh thự mùa hè thời thuộc địa của vị hoàng đế cuối cùng Việt Nam."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Palace III is a museum that displays the beautiful original 1930s furniture."
    },
    {
      "name": "Flower Garden",
      "local_name": "Vườn hoa Đà Lạt",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A set of flower gardens centred around a reconstructed traditional Vietnamese teak wood house, easy to visit as a stop when strolling around the lake.",
        "vi": "Một quần thể vườn hoa xoay quanh một ngôi nhà gỗ lim truyền thống Việt Nam được phục dựng, có thể ghé thăm khi dạo quanh hồ."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A set of flower gardens centred around a reconstructed traditional Vietnamese teak wood house."
    },
    {
      "name": "Prenn Falls",
      "local_name": "Thác Prenn",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A very common stop on a typical Dalat tour, quite beautiful but a lot more fun when you're hiking it than just taking pictures of it.",
        "vi": "Một điểm dừng rất phổ biến trong tour Đà Lạt điển hình, khá đẹp nhưng thú vị hơn nhiều khi bạn leo bộ thay vì chỉ chụp ảnh."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A very common stop on a typical Dalat tour, Prenn Falls is quite beautiful, but is a lot more fun when you're hiking it than just taking pictures of it."
    },
    {
      "name": "Lake of Sorrow",
      "local_name": "Hồ Than Thở",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A common destination in Dalat, named after a tale of two lovers, one who committed suicide after the other was called up to serve in the army.",
        "vi": "Một điểm đến quen thuộc ở Đà Lạt, được đặt tên theo câu chuyện về đôi tình nhân, một người đã tự tử sau khi người kia bị gọi nhập ngũ."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The Lake of Sorrow is so-named because of a tale of two lovers, one who committed suicide after the other was called up to serve in the army."
    },
    {
      "name": "Golden Spring Lake",
      "local_name": "Hồ Suối Vàng",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A lake with unspoiled scenery, a peaceful natural spot to enjoy the landscape.",
        "vi": "Một hồ nước với cảnh quan hoang sơ, nơi yên bình để tận hưởng thiên nhiên."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Golden Spring Lake (Ho Suoi Vang). Unspoiled scenery."
    }
  ],
  "eateries": [
    {
      "name": "Dalat (Central) Market",
      "local_name": "Chợ Đà Lạt",
      "dish": null,
      "why": {
        "en": "The best place in town to eat fresh fruits and vegetables, with a lively vegetable restaurant near the entrance serving excellent soups.",
        "vi": "Nơi tuyệt nhất trong thành phố để ăn trái cây và rau củ tươi, gần lối vào có một quán rau luôn đông khách phục vụ các món súp tuyệt hảo."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Dalat's Central Market place is the best place in town to eat fresh fruits and vegetables."
    },
    {
      "name": "Vcafe restaurant",
      "local_name": "Vcafe",
      "dish": null,
      "why": {
        "en": "A popular place for Western travellers with a diverse menu of international dishes and live music every evening.",
        "vi": "Một nơi được du khách phương Tây yêu thích với thực đơn đa dạng các món quốc tế và nhạc sống mỗi tối."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Popular place for Western travellers. Diverse menu of international dishes and live music every evening."
    },
    {
      "name": "IndiaGate",
      "local_name": "IndiaGate",
      "dish": null,
      "why": {
        "en": "An Indian restaurant with vegan and halal options available.",
        "vi": "Một nhà hàng Ấn Độ có các lựa chọn thuần chay và halal."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Indian restaurant. Vegan and halal options available."
    },
    {
      "name": "Fungi Chingu Chợ Đêm",
      "local_name": "Fungi Chingu Chợ Đêm",
      "dish": null,
      "why": {
        "en": "A Korean BBQ restaurant in the night market area.",
        "vi": "Một quán nướng Hàn Quốc ở khu chợ đêm."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Fungi Chingu Chợ Đêm - Quán nướng Hàn Quốc. Korean BBQ"
    },
    {
      "name": "Dalat Palace Golf Club",
      "local_name": "Dalat Palace Golf Club",
      "dish": null,
      "why": {
        "en": "A cafe, pro shop and clubhouse offering Mexican and Western food with a great view of the deep green fairways.",
        "vi": "Một quán cà phê, cửa hàng dụng cụ và nhà câu lạc bộ phục vụ đồ ăn Mexico và phương Tây với tầm nhìn tuyệt đẹp ra những thảm cỏ xanh thẫm."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Cafe, pro shop and clubhouse, offering Mexican and Western food."
    },
    {
      "name": "Bánh Mì Xíu Mại Ri 79",
      "local_name": "Bánh Mì Xíu Mại Ri 79",
      "dish": "Bánh mì xíu mại",
      "why": {
        "en": "A budget spot known for its bánh mì xíu mại, a Vietnamese baguette with meatballs.",
        "vi": "Một quán bình dân nổi tiếng với món bánh mì xíu mại."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Bánh Mì Xíu Mại Ri 79."
    },
    {
      "name": "Bánh ướt lòng gà LONG",
      "local_name": "Bánh ướt lòng gà LONG",
      "dish": "Bánh ướt lòng gà",
      "why": {
        "en": "A budget eatery known for bánh ướt lòng gà, steamed rice sheets with chicken offal.",
        "vi": "Một quán bình dân nổi tiếng với món bánh ướt lòng gà."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Bánh ướt lòng gà LONG."
    },
    {
      "name": "Sữa đậu nành Nguyễn Văn Cừ",
      "local_name": "Sữa đậu nành Nguyễn Văn Cừ",
      "dish": "Sữa đậu nành",
      "why": {
        "en": "A soya milk stall on Nguyen Van Cu street, a simple local drink stop.",
        "vi": "Một quầy sữa đậu nành trên đường Nguyễn Văn Cừ, nơi dừng chân uống nước bình dân của người địa phương."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Sữa đậu nành Nguyễn Văn Cừ -Soya Milk Stall."
    },
    {
      "name": "Cơm chay Thanh Đạm",
      "local_name": "Cơm chay Thanh Đạm",
      "dish": "Cơm chay",
      "why": {
        "en": "A budget vegetarian rice restaurant in Dalat.",
        "vi": "Một quán cơm chay bình dân ở Đà Lạt."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Cơm chay Thanh Đạm."
    },
    {
      "name": "Quán Cơm chay An Lạc Tâm",
      "local_name": "Quán Cơm chay An Lạc Tâm",
      "dish": "Cơm chay",
      "why": {
        "en": "A budget vegetarian rice restaurant in Dalat.",
        "vi": "Một quán cơm chay bình dân ở Đà Lạt."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Quán Cơm chay An Lạc Tâm."
    },
    {
      "name": "Goc ha thanh",
      "local_name": "Góc Hà Thành",
      "dish": null,
      "why": {
        "en": "A mid-range restaurant in Dalat serving Hanoi-style food.",
        "vi": "Một nhà hàng tầm trung ở Đà Lạt phục vụ các món ăn kiểu Hà Nội."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Goc ha thanh."
    }
  ],
